#if UNITY_EDITOR
using System;using System.IO;using UnityEngine;using Meteor.Launcher;
public static class MeteorOwnedContentProbe {
 public static void BuildIOS(){if(Environment.GetEnvironmentVariable("METEOR_BUILD_PRIVATE_CONTENT")!="YES")throw new Exception("Explicit private-resource opt-in required");string output=Environment.GetEnvironmentVariable("METEOR_PRIVATE_CONTENT_OUTPUT");if(String.IsNullOrEmpty(output)||!Path.IsPathRooted(output))throw new Exception("Absolute private output required");MeteorResourceBuild.ExportContent(output);}
 public static void LoadIOSData(){string source=Environment.GetEnvironmentVariable("METEOR_PRIVATE_CONTENT_OUTPUT"),storage=Environment.GetEnvironmentVariable("METEOR_PRIVATE_CONTENT_TEST_STORAGE");if(String.IsNullOrEmpty(source)||String.IsNullOrEmpty(storage))throw new Exception("Explicit test paths required");using(var tx=new ContentInstall(storage,"ios")){foreach(string name in new[]{"resources.bundle","scenes.bundle","resources.index","content.manifest"})using(var stream=File.OpenRead(Path.Combine(source,name)))tx.Receive(name,stream,stream.Length,()=>false);string root=tx.Commit();try{ContentResources.Mount(root,"ios");var level=ContentResources.Load<TextAsset>("Level");var fight=ContentResources.Load<GameObject>("UI/Dialogs/FightWnd");if(level==null||fight==null)throw new Exception("Actual typed resource missing");if(NodeHelper.Find("Defence",fight)==null||NodeHelper.Find("Jump",fight)==null)throw new Exception("Native controls missing from external prefab");var ui=UnityEngine.Object.Instantiate(fight);try{CustomCombatControls.Bind(ui);if(ui.GetComponentsInChildren<ConfiguredActionButton>(true).Length!=9)throw new Exception("Configured buttons missing");var defence=NodeHelper.Find("Defence",ui);if(!defence.activeSelf)throw new Exception("Defence not visible");if(NodeHelper.Find("LongJump",ui)==null&&NodeHelper.Find("Configured_LongJump",ui)==null)throw new Exception("LongJump missing");}finally{UnityEngine.Object.DestroyImmediate(ui);}
File.WriteAllText(Path.Combine(storage,"data-probe.txt"),"PASS actual iOS bundles mounted in Editor diagnostic; Level bytes="+level.text.Length+"; FightWnd prefab, Defence and Jump present; actual Bind produced nine configured buttons, visible Defence and LongJump. No gameplay/visual/device claim.\n");}finally{ContentResources.Unmount();}}}
}
#endif
